import{_ as t,c as a,o,ae as r}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse('{"title":"About Us","description":"Information about the MinecraftSounds team and project","frontmatter":{"title":"About Us","description":"Information about the MinecraftSounds team and project"},"headers":[],"relativePath":"en/about.md","filePath":"en/about.md"}'),n={name:"en/about.md"};function i(s,e,c,l,u,d){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="about-minecraftsounds" tabindex="-1">About MinecraftSounds <a class="header-anchor" href="#about-minecraftsounds" aria-label="Permalink to &quot;About MinecraftSounds&quot;">​</a></h1><h2 id="project-introduction" tabindex="-1">Project Introduction <a class="header-anchor" href="#project-introduction" aria-label="Permalink to &quot;Project Introduction&quot;">​</a></h2><p>MinecraftSounds Music Pack Generator is a music pack generation tool designed specifically for Minecraft players, aimed at enabling players to easily create, manage, and share custom game sound effects and music. Our goal is to allow everyone, regardless of programming experience, to create professional music packs.</p><h2 id="core-members" tabindex="-1">Core Members <a class="header-anchor" href="#core-members" aria-label="Permalink to &quot;Core Members&quot;">​</a></h2><ul><li><strong>小阿狼是也 (XiaoALangShiYe)</strong> - Project Lead &amp; Main Programmer</li></ul><h2 id="project-history" tabindex="-1">Project History <a class="header-anchor" href="#project-history" aria-label="Permalink to &quot;Project History&quot;">​</a></h2><p>The MinecraftSounds Music Pack Generator project began in early August 2025, when we noticed that many players wanted to play their own music or audio but struggled as beginners who didn&#39;t know how to manually create music packs and lacked simple, easy-to-use tools.</p><p>Taking three days (August 10-13, 2025), the first test version of MinecraftSounds Music Pack Generator was developed by 小阿狼是也 and produced by 零一狼AL01.</p><h2 id="technology-stack" tabindex="-1">Technology Stack <a class="header-anchor" href="#technology-stack" aria-label="Permalink to &quot;Technology Stack&quot;">​</a></h2><p>MinecraftSounds Music Pack Generator is built using the following technologies:</p><ul><li><strong>Python</strong> - Programming language used for the software</li><li><strong>PyQt5</strong> - Used for building the user interface</li><li><strong>FFmpeg</strong> - Used for audio processing</li><li><strong>PyInstaller</strong> - Used for packaging the software</li><li><strong>Documentation website</strong>: VitePress</li></ul><h2 id="open-source-license" tabindex="-1">Open Source License <a class="header-anchor" href="#open-source-license" aria-label="Permalink to &quot;Open Source License&quot;">​</a></h2><p>MinecraftSounds Music Pack Generator is released under the GPL-2.0 open source license, which is a free and open software license. Under this license, you are free to use, study, modify, and distribute this software, but you must ensure that derivative works also adopt the GPL-2.0 license and retain the original copyright notice and license information. We believe that the open source spirit can promote community collaboration and drive continuous project development.</p><h2 id="support-us" tabindex="-1">Support Us <a class="header-anchor" href="#support-us" aria-label="Permalink to &quot;Support Us&quot;">​</a></h2><p>If you like MinecraftSounds Music Pack Generator, you can support us in the following ways:</p><ul><li>Star the project on <a href="https://github.com/al01cn/MinecraftSounds" target="_blank" rel="noreferrer">GitHub</a></li><li>Star the project on <a href="https://gitee.com/al01/minecraft-sounds" target="_blank" rel="noreferrer">Gitee</a></li><li>Recommend our tool to your friends</li><li>Report bugs or submit feature requests</li><li>Contribute code or documentation</li></ul><h2 id="contact-us" tabindex="-1">Contact Us <a class="header-anchor" href="#contact-us" aria-label="Permalink to &quot;Contact Us&quot;">​</a></h2><ul><li><strong>GitHub</strong>: <a href="https://github.com/al01cn/MinecraftSounds" target="_blank" rel="noreferrer">github.com/al01cn/MinecraftSounds</a></li><li><strong>Gitee</strong>: <a href="https://gitee.com/al01/minecraft-sounds" target="_blank" rel="noreferrer">gitee.com/al01/minecraft-sounds</a></li><li><strong>Email</strong>: <a href="mailto:contact@al01.cn" target="_blank" rel="noreferrer">contact@al01.cn</a></li></ul>',18)]))}const f=t(n,[["render",i]]);export{p as __pageData,f as default};
